'use strict';

// Convention: a value of the wrong type raises TypeError; a value of the right
// type that is out of range, non-finite, fractional or blank raises RangeError.

/**
 * Renders a value for an error message. Avoids String() on plain objects
 * because null-prototype objects throw when coerced.
 * @param {unknown} value
 * @returns {string}
 */
function describeValue(value) {
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null || typeof value !== 'object') return String(value);
  return Array.isArray(value) ? 'an array' : 'an object';
}

/**
 * @param {unknown} value
 * @param {string} label Name of the argument, used in the error message.
 * @throws {TypeError} If `value` is not a string.
 * @throws {RangeError} If `value` is empty or whitespace-only.
 */
function assertNonEmptyString(value, label) {
  if (typeof value !== 'string') {
    throw new TypeError(`${label} must be a string, received ${describeValue(value)}`);
  }
  if (value.trim() === '') {
    throw new RangeError(`${label} must not be empty or whitespace-only, received ${describeValue(value)}`);
  }
}

/**
