'use strict';

// Totals are computed in integer minor units (cents for 2 decimal places) so
// that discounts and rounding are exact integer arithmetic until the final
// conversion back, instead of accumulating binary floating-point error.

/** Default number of decimal places in the currency's minor unit (cents). */
const DEFAULT_DECIMAL_PLACES = 2;

/**
 * Largest supported precision. Past 8 places, a total of about 90 million
 * would already exceed Number.MAX_SAFE_INTEGER in minor units.
 */
const MAX_DECIMAL_PLACES = 8;

/**
 * Converts an amount to integer minor units, rounding half up.
 * Callers pass a finite, non-negative amount.
 * @param {number} amount
 * @param {number} decimalPlaces Integer from 0 to MAX_DECIMAL_PLACES.
 * @returns {number} A safe integer.
 * @throws {RangeError} If the result cannot be represented exactly.
 */
function toMinorUnits(amount, decimalPlaces) {
  const minorUnits = Math.round(amount * 10 ** decimalPlaces);
  if (!Number.isSafeInteger(minorUnits)) {
    throw new RangeError(
      `amount ${amount} is too large to represent exactly with ${decimalPlaces} decimal places`,
    );
  }
  return minorUnits;
}

/**
 * @param {number} minorUnits Integer amount in minor units.
 * @param {number} decimalPlaces Integer from 0 to MAX_DECIMAL_PLACES.
 * @returns {number}
 */
function fromMinorUnits(minorUnits, decimalPlaces) {
  return minorUnits / 10 ** decimalPlaces;
}

/**
 * Takes `percent` off an amount, rounding the discounted result half up once.
 * @param {number} minorUnits Integer amount in minor units.
 * @param {number} percent From 0 to 100.
 * @returns {number} Discounted amount in minor units.
 */
function applyPercentDiscount(minorUnits, percent) {
  return Math.round((minorUnits * (100 - percent)) / 100);
}

module.exports = {
  DEFAULT_DECIMAL_PLACES,
  MAX_DECIMAL_PLACES,
  toMinorUnits,
  fromMinorUnits,
  applyPercentDiscount,
};

