'use strict';

const { assertNonEmptyString, assertNumberInRange } = require('./validation');
const {
  DEFAULT_DECIMAL_PLACES,
  MAX_DECIMAL_PLACES,
  toMinorUnits,
  fromMinorUnits,
  applyPercentDiscount,
} = require('./money');

const DEFAULT_QUANTITY = 1;
const MIN_DISCOUNT_PERCENT = 0;
const MAX_DISCOUNT_PERCENT = 100;

/**
 * A cart of named line items with an optional percentage discount.
 *
 * Invalid arguments throw TypeError (wrong type) or RangeError (right type,
 * unacceptable value) before any state changes, so a rejected call leaves the
 * cart exactly as it was.
 */
class ShoppingCart {
  /**
   * @param {object} [options]
   * @param {number} [options.decimalPlaces=2] Decimal places that totals are
   *   rounded to: 2 for most currencies, 0 for JPY, 3 for KWD.
   */
  constructor(options = {}) {
    if (options === null || typeof options !== 'object') {
      throw new TypeError(
        `options must be an object, received ${options === null ? 'null' : typeof options}`,
      );
    }
    const { decimalPlaces = DEFAULT_DECIMAL_PLACES } = options;
    assertNumberInRange(decimalPlaces, 'decimalPlaces', {
      min: 0,
      max: MAX_DECIMAL_PLACES,
      integer: true,
    });

    this.items = [];
    this.discount = 0;
    this.decimalPlaces = decimalPlaces;
  }

  /**
   * Adds a line item, or increases the quantity of the existing line with the
   * same name. A repeat add keeps the unit price from the first add.
   * @param {string} name Non-blank; matched exactly and case-sensitively.
   * @param {number} price Unit price; finite and at least 0.
   * @param {number} [quantity=1] Whole number, at least 1.
   */
  addItem(name, price, quantity = DEFAULT_QUANTITY) {
    assertNonEmptyString(name, 'name');
    assertNumberInRange(price, 'price', { min: 0 });
    assertNumberInRange(quantity, 'quantity', { min: 1, integer: true });

    const existing = this.items.find((item) => item.name === name);
    if (!existing) {
      this.items.push({ name, price, quantity });
      return;
    }

    const mergedQuantity = existing.quantity + quantity;
    if (!Number.isSafeInteger(mergedQuantity)) {
      throw new RangeError(
        `adding ${quantity} to the ${existing.quantity} of ${JSON.stringify(name)} already in the cart ` +
          'would exceed Number.MAX_SAFE_INTEGER',
      );
    }
    existing.quantity = mergedQuantity;
  }

  /**
   * Removes the line with this exact name, whatever its quantity.
   * @param {string} name
   * @returns {boolean} true if a line was removed, false if no line matched.
   */
  removeItem(name) {
    assertNonEmptyString(name, 'name');

    const index = this.items.findIndex((item) => item.name === name);
    if (index === -1) return false;
    this.items.splice(index, 1);
    return true;
  }

  /**
   * @returns {number} Sum of price × quantity for every line, minus the
   *   discount, rounded half up to `decimalPlaces`.
   * @throws {RangeError} If the total is too large to represent exactly.
   */
  getTotal() {
    const subtotal = this.items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    const subtotalMinorUnits = toMinorUnits(subtotal, this.decimalPlaces);
    const totalMinorUnits = applyPercentDiscount(subtotalMinorUnits, this.discount);
    return fromMinorUnits(totalMinorUnits, this.decimalPlaces);
  }

  /**
   * Sets the discount, replacing any previous one. Discounts do not stack.
   * @param {number} percent From 0 to 100 inclusive; fractions are allowed.
   */
  applyDiscount(percent) {
    assertNumberInRange(percent, 'discount percent', {
      min: MIN_DISCOUNT_PERCENT,
      max: MAX_DISCOUNT_PERCENT,
    });
    this.discount = percent;
  }

  /**
   * @returns {number} Number of distinct line items, not the total quantity.
   */
  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

