'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');

describe('ShoppingCart numeric boundaries', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  it('accepts a quantity of exactly Number.MAX_SAFE_INTEGER', () => {
    cart.addItem('Grain', 0, Number.MAX_SAFE_INTEGER);
    assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
    assert.equal(cart.getTotal(), 0);
  });

  it('rejects a quantity above Number.MAX_SAFE_INTEGER', () => {
    assert.throws(() => cart.addItem('Grain', 1, 2 ** 53), { name: 'RangeError', message: /quantity/ });
  });

  it('rejects a merge that would push quantity past Number.MAX_SAFE_INTEGER and keeps the old quantity', () => {
    cart.addItem('Grain', 0, Number.MAX_SAFE_INTEGER);
    assert.throws(() => cart.addItem('Grain', 0, 1), {
      name: 'RangeError',
      message: /"Grain".*MAX_SAFE_INTEGER/,
    });
    assert.equal(cart.items[0].quantity, Number.MAX_SAFE_INTEGER);
  });

  it('throws a RangeError from getTotal when the total is too large to represent exactly', () => {
    cart.addItem('Planet', 1e300, 1);
    assert.throws(() => cart.getTotal(), { name: 'RangeError', message: /too large/ });
  });

  it('throws a RangeError from getTotal when the subtotal overflows to Infinity', () => {
    cart.addItem('Galaxy', Number.MAX_VALUE, 2);
    assert.throws(() => cart.getTotal(), RangeError);
  });

  it('accepts the smallest positive price and rounds it away in the total', () => {
    cart.addItem('Dust', Number.MIN_VALUE, 1);
    assert.equal(cart.getTotal(), 0);
  });

  it('rounds a sub-cent unit price half up at the subtotal', () => {
    cart.addItem('Screw', 0.125, 1);
    assert.equal(cart.getTotal(), 0.13);
  });

  it('keeps sub-cent unit prices exact across quantity before rounding', () => {
    cart.addItem('Screw', 0.125, 1000);
    assert.equal(cart.getTotal(), 125);
  });

  it('rounds a repeating-decimal discount to the nearest cent', () => {
    cart.addItem('Desk', 100, 1);
    cart.applyDiscount(100 / 3);
    assert.equal(cart.getTotal(), 66.67);
  });
});

describe('ShoppingCart item names', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  it('supports unicode names with accents, CJK characters and emoji', () => {
    cart.addItem('Café au lait', 3.2, 1);
    cart.addItem('抹茶ラテ', 4.8, 1);
    cart.addItem('🍎', 0.99, 1);
    assert.equal(cart.getTotal(), 8.99);

    assert.equal(cart.removeItem('抹茶ラテ'), true);
    assert.deepEqual(
      cart.items.map((item) => item.name),
      ['Café au lait', '🍎'],
    );
    assert.equal(cart.getTotal(), 4.19);
  });

  it('treats differently encoded forms of the same text as different names (no Unicode normalization)', () => {
    cart.addItem('Café', 1, 1);
    cart.addItem('Café', 1, 1);
    assert.equal(cart.getItemCount(), 2);
  });

  it('treats names case-sensitively', () => {
    cart.addItem('Apple', 1, 1);
    cart.addItem('apple', 1, 1);
    assert.equal(cart.getItemCount(), 2);
  });

  it('does not trim names, so surrounding whitespace makes a distinct item', () => {
    cart.addItem('Apple', 1, 1);
    cart.addItem(' Apple ', 1, 1);
    assert.equal(cart.getItemCount(), 2);
    assert.equal(cart.removeItem('Apple'), true);
    assert.equal(cart.items[0].name, ' Apple ');
  });

  it('handles a 10,000-character name', () => {
    const name = 'x'.repeat(10_000);
    cart.addItem(name, 2, 1);
    cart.addItem(name, 2, 1);
    assert.equal(cart.items[0].quantity, 2);
    assert.equal(cart.removeItem(name), true);
  });

  it('treats names such as __proto__ and constructor as ordinary items', () => {
    for (const name of ['__proto__', 'constructor', 'toString']) {
      cart.addItem(name, 1, 1);
    }
    assert.equal(cart.getItemCount(), 3);
    assert.equal(cart.removeItem('__proto__'), true);
    assert.equal(cart.getTotal(), 2);
  });
});

describe('ShoppingCart burst and large inputs', () => {
  it('totals 10,000 one-cent line items to exactly 100', () => {
    const cart = new ShoppingCart();
    for (let i = 0; i < 10_000; i += 1) {
      cart.addItem(`item-${i}`, 0.01, 1);
    }
    assert.equal(cart.getItemCount(), 10_000);
    assert.equal(cart.getTotal(), 100);
  });

  it('merges 1,000 rapid repeat adds into one line', () => {
    const cart = new ShoppingCart();
    for (let i = 0; i < 1_000; i += 1) {
      cart.addItem('Gum', 0.25);
    }
    assert.equal(cart.getItemCount(), 1);
    assert.equal(cart.items[0].quantity, 1_000);
    assert.equal(cart.getTotal(), 250);
  });

  it('removes one item from the middle of a large cart and keeps the rest in order', () => {
    const cart = new ShoppingCart();
    for (let i = 0; i < 1_000; i += 1) {
      cart.addItem(`item-${i}`, 1, 1);
    }
    assert.equal(cart.removeItem('item-500'), true);
    assert.equal(cart.getItemCount(), 999);
    assert.equal(cart.items[499].name, 'item-499');
    assert.equal(cart.items[500].name, 'item-501');
  });
});

describe('ShoppingCart state isolation and side effects', () => {
  it('keeps items and discounts separate between cart instances', () => {
    const first = new ShoppingCart();
    const second = new ShoppingCart();
    first.addItem('Apple', 1, 3);
    first.applyDiscount(50);
    second.addItem('Bread', 4, 1);

    assert.deepEqual(first.items, [{ name: 'Apple', price: 1, quantity: 3 }]);
    assert.deepEqual(second.items, [{ name: 'Bread', price: 4, quantity: 1 }]);
    assert.equal(second.discount, 0);
    assert.equal(second.getTotal(), 4);
  });

  it('keeps decimalPlaces separate between cart instances', () => {
    const yen = new ShoppingCart({ decimalPlaces: 0 });
    const dollars = new ShoppingCart();
    yen.addItem('Onigiri', 150.4, 1);
    dollars.addItem('Onigiri', 150.4, 1);
    assert.equal(yen.getTotal(), 150);
    assert.equal(dollars.getTotal(), 150.4);
  });

  it('does not mutate items when reading the total or item count', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 2);
    cart.addItem('Bread', 2.25, 1);
    cart.applyDiscount(10);
    const before = structuredClone(cart.items);

    const firstTotal = cart.getTotal();
    cart.getItemCount();
    assert.equal(cart.getTotal(), firstTotal);
    assert.deepEqual(cart.items, before);
    assert.equal(cart.discount, 10);
  });

  it('removes items in place, so an existing reference to cart.items stays current', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 1, 1);
    cart.addItem('Bread', 2, 1);
    const itemsRef = cart.items;
    cart.removeItem('Apple');
    assert.equal(cart.items, itemsRef);
    assert.deepEqual(itemsRef, [{ name: 'Bread', price: 2, quantity: 1 }]);
  });

  it('does not reuse the options object passed to the constructor', () => {
    const options = { decimalPlaces: 0 };
    const cart = new ShoppingCart(options);
    options.decimalPlaces = 2;
    cart.addItem('Ramen', 850.4, 1);
    assert.equal(cart.getTotal(), 850);
    assert.deepEqual(options, { decimalPlaces: 2 });
  });

  it('ignores unknown option keys', () => {
    const cart = new ShoppingCart({ currency: 'EUR' });
    cart.addItem('Croissant', 1.8, 2);
    assert.equal(cart.getTotal(), 3.6);
  });
});

