'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

const { assertNonEmptyString, assertNumberInRange } = require('../src/validation');

describe('assertNonEmptyString', () => {
  it('accepts non-blank strings, including ones with surrounding whitespace', () => {
    assert.doesNotThrow(() => assertNonEmptyString('a', 'name'));
    assert.doesNotThrow(() => assertNonEmptyString('  a  ', 'name'));
  });

  it('rejects non-strings with a TypeError naming the label', () => {
    assert.throws(() => assertNonEmptyString(5, 'name'), {
      name: 'TypeError',
      message: 'name must be a string, received 5',
    });
  });

  it('rejects empty and whitespace-only strings with a RangeError', () => {
    assert.throws(() => assertNonEmptyString('', 'name'), {
      name: 'RangeError',
      message: 'name must not be empty or whitespace-only, received ""',
    });
    assert.throws(() => assertNonEmptyString(' \t\n', 'name'), RangeError);
  });

  const describedValues = [
    { label: 'null', value: null, expected: 'null' },
    { label: 'undefined', value: undefined, expected: 'undefined' },
    { label: 'an array', value: ['a'], expected: 'an array' },
    { label: 'a plain object', value: { a: 1 }, expected: 'an object' },
    { label: 'a null-prototype object', value: Object.create(null), expected: 'an object' },
    { label: 'a function', value: () => 'secret', expected: 'a function' },
    { label: 'a bigint', value: 5n, expected: '5n' },
    { label: 'a symbol', value: Symbol('tag'), expected: 'Symbol(tag)' },
    { label: 'a boolean', value: true, expected: 'true' },
  ];
  for (const { label, value, expected } of describedValues) {
    it(`describes ${label} in the error message without throwing while formatting`, () => {
      assert.throws(() => assertNonEmptyString(value, 'name'), {
        name: 'TypeError',
        message: `name must be a string, received ${expected}`,
      });
    });
  }
});

describe('assertNumberInRange', () => {
  it('accepts values at the inclusive min and max', () => {
    assert.doesNotThrow(() => assertNumberInRange(0, 'n', { min: 0, max: 100 }));
    assert.doesNotThrow(() => assertNumberInRange(100, 'n', { min: 0, max: 100 }));
  });

  it('rejects values just outside the bounds with a RangeError', () => {
    assert.throws(() => assertNumberInRange(-0.001, 'n', { min: 0 }), {
      name: 'RangeError',
      message: 'n must be at least 0, received -0.001',
    });
    assert.throws(() => assertNumberInRange(100.001, 'n', { max: 100 }), {
      name: 'RangeError',
      message: 'n must be at most 100, received 100.001',
    });
  });

  it('is unbounded when no bounds are given', () => {
    assert.doesNotThrow(() => assertNumberInRange(-1e300, 'n'));
    assert.doesNotThrow(() => assertNumberInRange(1e300, 'n'));
  });

  it('rejects NaN and infinities with a RangeError even without bounds', () => {
    for (const value of [NaN, Infinity, -Infinity]) {
      assert.throws(() => assertNumberInRange(value, 'n'), {
        name: 'RangeError',
        message: `n must be a finite number, received ${value}`,
      });
    }
  });

  it('rejects non-number types with a TypeError', () => {
    assert.throws(() => assertNumberInRange('1', 'n'), {
      name: 'TypeError',
      message: 'n must be a number, received "1"',
    });
    assert.throws(() => assertNumberInRange(new Number(1), 'n'), TypeError);
  });

  it('accepts safe integers when integer is set', () => {
    assert.doesNotThrow(() => assertNumberInRange(Number.MAX_SAFE_INTEGER, 'n', { integer: true }));
    assert.doesNotThrow(() => assertNumberInRange(-3, 'n', { integer: true }));
  });

  it('rejects fractions and unsafe integers when integer is set', () => {
    for (const value of [1.5, 2 ** 53]) {
      assert.throws(() => assertNumberInRange(value, 'n', { integer: true }), {
        name: 'RangeError',
        message: /n must be a whole number/,
      });
    }
  });
});

