'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

const {
  DEFAULT_DECIMAL_PLACES,
  MAX_DECIMAL_PLACES,
  toMinorUnits,
  fromMinorUnits,
  applyPercentDiscount,
} = require('../src/money');

describe('toMinorUnits', () => {
  const cases = [
    { amount: 19.99, places: 2, expected: 1999 },
    { amount: 0.1 * 3, places: 2, expected: 30 },
    { amount: 0.125, places: 2, expected: 13 },
    { amount: 0.124, places: 2, expected: 12 },
    { amount: 850, places: 0, expected: 850 },
    { amount: 0.375, places: 3, expected: 375 },
    { amount: 0, places: 2, expected: 0 },
  ];
  for (const { amount, places, expected } of cases) {
    it(`converts ${amount} at ${places} decimal places to ${expected}`, () => {
      assert.equal(toMinorUnits(amount, places), expected);
    });
  }

  it('supports MAX_DECIMAL_PLACES for ordinary amounts', () => {
    assert.equal(toMinorUnits(1.5, MAX_DECIMAL_PLACES), 1.5 * 10 ** MAX_DECIMAL_PLACES);
  });

  it('throws a RangeError when the result is not a safe integer', () => {
    assert.throws(() => toMinorUnits(1e300, 2), { name: 'RangeError', message: /too large/ });
    assert.throws(() => toMinorUnits(Number.MAX_SAFE_INTEGER, 2), RangeError);
    assert.throws(() => toMinorUnits(Infinity, 2), RangeError);
  });
});

describe('fromMinorUnits', () => {
  it('converts minor units back to the nearest representable amount', () => {
    assert.equal(fromMinorUnits(1999, 2), 19.99);
    assert.equal(fromMinorUnits(723, 0), 723);
    assert.equal(fromMinorUnits(375, 3), 0.375);
    assert.equal(fromMinorUnits(0, DEFAULT_DECIMAL_PLACES), 0);
  });

  it('round-trips amounts with DEFAULT_DECIMAL_PLACES', () => {
    for (const amount of [0.01, 0.1, 1.23, 59.97, 1234567.89]) {
      assert.equal(fromMinorUnits(toMinorUnits(amount, DEFAULT_DECIMAL_PLACES), DEFAULT_DECIMAL_PLACES), amount);
    }
  });
});

describe('applyPercentDiscount', () => {
  it('subtracts the percentage from the amount', () => {
    assert.equal(applyPercentDiscount(10_000, 10), 9_000);
    assert.equal(applyPercentDiscount(10_000, 12.5), 8_750);
  });

  it('returns the amount unchanged at 0% and zero at 100%', () => {
    assert.equal(applyPercentDiscount(10_000, 0), 10_000);
    assert.equal(applyPercentDiscount(10_000, 100), 0);
  });

  it('rounds an exact half minor unit up', () => {
    assert.equal(applyPercentDiscount(3_150, 15), 2_678);
    assert.equal(applyPercentDiscount(1, 50), 1);
  });

  it('returns zero for a zero amount', () => {
    assert.equal(applyPercentDiscount(0, 50), 0);
  });
});

