'use strict';

const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');

const ShoppingCart = require('../src/cart');

describe('ShoppingCart constructor', () => {
  it('starts with no items and no discount', () => {
    const cart = new ShoppingCart();
    assert.deepEqual(cart.items, []);
    assert.equal(cart.discount, 0);
    assert.equal(cart.getItemCount(), 0);
  });

  it('rounds totals to whole units when decimalPlaces is 0 (e.g. JPY)', () => {
    const cart = new ShoppingCart({ decimalPlaces: 0 });
    cart.addItem('Ramen', 850, 1);
    cart.applyDiscount(15);
    assert.equal(cart.getTotal(), 723);
  });

  it('keeps three decimal places when decimalPlaces is 3 (e.g. KWD)', () => {
    const cart = new ShoppingCart({ decimalPlaces: 3 });
    cart.addItem('Bolt', 0.125, 3);
    assert.equal(cart.getTotal(), 0.375);
  });

  const invalidDecimalPlaces = [
    { value: -1, error: RangeError },
    { value: 1.5, error: RangeError },
    { value: 9, error: RangeError },
    { value: '2', error: TypeError },
  ];
  for (const { value, error } of invalidDecimalPlaces) {
    it(`rejects decimalPlaces ${JSON.stringify(value)} with a ${error.name}`, () => {
      assert.throws(() => new ShoppingCart({ decimalPlaces: value }), {
        name: error.name,
        message: /decimalPlaces/,
      });
    });
  }

  for (const options of [null, 2, 'cents']) {
    it(`rejects non-object options ${JSON.stringify(options)} with a TypeError`, () => {
      assert.throws(() => new ShoppingCart(options), { name: 'TypeError', message: /options/ });
    });
  }
});

describe('ShoppingCart#addItem', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  it('adds a new line item with the given name, price and quantity', () => {
    cart.addItem('Apple', 0.5, 4);
    assert.deepEqual(cart.items, [{ name: 'Apple', price: 0.5, quantity: 4 }]);
  });

  it('defaults quantity to 1 when it is omitted', () => {
    cart.addItem('Book', 12);
    assert.deepEqual(cart.items, [{ name: 'Book', price: 12, quantity: 1 }]);
  });

  it('merges quantity into the existing line when the same name is added again', () => {
    cart.addItem('Apple', 0.5, 2);
    cart.addItem('Apple', 0.5, 3);
    assert.equal(cart.getItemCount(), 1);
    assert.equal(cart.items[0].quantity, 5);
  });

  it('keeps the first unit price when an existing item is added again', () => {
    cart.addItem('Apple', 0.5, 1);
    cart.addItem('Apple', 0.75, 1);
    assert.deepEqual(cart.items, [{ name: 'Apple', price: 0.5, quantity: 2 }]);
  });

  it('accepts a price of zero for free items', () => {
    cart.addItem('Sticker', 0, 2);
    assert.equal(cart.getTotal(), 0);
    assert.equal(cart.getItemCount(), 1);
  });

  describe('Bug 1 regression: rejects negative or otherwise invalid price and quantity', () => {
    it('rejects a negative price with a RangeError and does not add the item', () => {
      assert.throws(() => cart.addItem('Apple', -1, 1), {
        name: 'RangeError',
        message: /price must be at least 0, received -1/,
      });
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a negative quantity with a RangeError and does not add the item', () => {
      assert.throws(() => cart.addItem('Apple', 1, -2), {
        name: 'RangeError',
        message: /quantity must be at least 1, received -2/,
      });
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a zero quantity', () => {
      assert.throws(() => cart.addItem('Apple', 1, 0), { name: 'RangeError', message: /quantity/ });
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('Apple', 1, 1.5), { name: 'RangeError', message: /quantity/ });
    });

    it('rejects a negative quantity for an item already in the cart and keeps its quantity', () => {
      cart.addItem('Apple', 1, 3);
      assert.throws(() => cart.addItem('Apple', 1, -5), RangeError);
      assert.equal(cart.items[0].quantity, 3);
    });

    for (const price of [NaN, Infinity, -Infinity]) {
      it(`rejects a non-finite price (${price}) with a RangeError`, () => {
        assert.throws(() => cart.addItem('Apple', price, 1), { name: 'RangeError', message: /price/ });
      });
    }

    for (const price of ['5', null, {}, 5n]) {
      it(`rejects a non-number price (${typeof price}) with a TypeError`, () => {
        assert.throws(() => cart.addItem('Apple', price, 1), { name: 'TypeError', message: /price/ });
      });
    }

    it('rejects a non-number quantity such as the string "2" with a TypeError', () => {
      assert.throws(() => cart.addItem('Apple', 1, '2'), { name: 'TypeError', message: /quantity/ });
    });
  });

  describe('name validation', () => {
    for (const name of [undefined, 42, null, ['Apple']]) {
      it(`rejects a non-string name (${JSON.stringify(name)}) with a TypeError`, () => {
        assert.throws(() => cart.addItem(name, 1, 1), { name: 'TypeError', message: /name/ });
      });
    }

    for (const name of ['', '   ', '\t\n']) {
      it(`rejects a blank name ${JSON.stringify(name)} with a RangeError`, () => {
        assert.throws(() => cart.addItem(name, 1, 1), { name: 'RangeError', message: /name/ });
      });
    }
  });
});

describe('ShoppingCart#removeItem', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 2);
    cart.addItem('Bread', 2.25, 1);
    cart.addItem('Milk', 1.2, 3);
  });

  it('Bug 2 regression: removes only the named item and keeps the others', () => {
    cart.removeItem('Bread');
    assert.deepEqual(
      cart.items.map((item) => item.name),
      ['Apple', 'Milk'],
    );
  });

  it('Bug 2 regression: leaves the remaining items unmodified instead of renaming them', () => {
    cart.removeItem('Bread');
    assert.deepEqual(cart.items, [
      { name: 'Apple', price: 0.5, quantity: 2 },
      { name: 'Milk', price: 1.2, quantity: 3 },
    ]);
  });

  it('returns true when an item was removed', () => {
    assert.equal(cart.removeItem('Apple'), true);
    assert.equal(cart.getItemCount(), 2);
  });

  it('Bug 2 regression: returns false and leaves the cart unchanged when the item is missing', () => {
    const before = structuredClone(cart.items);
    assert.equal(cart.removeItem('Cheese'), false);
    assert.deepEqual(cart.items, before);
  });

  it('returns false when removing from an empty cart', () => {
    const empty = new ShoppingCart();
    assert.equal(empty.removeItem('Apple'), false);
    assert.equal(empty.getItemCount(), 0);
  });

  it('matches names exactly, so a differently cased name is not removed', () => {
    assert.equal(cart.removeItem('apple'), false);
    assert.equal(cart.getItemCount(), 3);
  });

  it('removes the whole line regardless of quantity', () => {
    cart.removeItem('Milk');
    assert.equal(
      cart.items.some((item) => item.name === 'Milk'),
      false,
    );
  });

  it('lets a removed item be added again as a fresh line', () => {
    cart.removeItem('Apple');
    cart.addItem('Apple', 0.6, 1);
    assert.deepEqual(cart.items.at(-1), { name: 'Apple', price: 0.6, quantity: 1 });
  });

  for (const name of [undefined, 7, null]) {
    it(`rejects a non-string name (${JSON.stringify(name)}) with a TypeError`, () => {
      assert.throws(() => cart.removeItem(name), { name: 'TypeError', message: /name/ });
      assert.equal(cart.getItemCount(), 3);
    });
  }
});

describe('ShoppingCart#getTotal', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  it('Bug 3 regression: returns 0 for an empty cart instead of throwing', () => {
    assert.equal(cart.getTotal(), 0);
  });

  it('Bug 3 regression: totals a single item without reading past the end of the list', () => {
    cart.addItem('Book', 12.5, 2);
    assert.equal(cart.getTotal(), 25);
  });

  it('sums price × quantity across every line', () => {
    cart.addItem('Apple', 0.5, 4);
    cart.addItem('Bread', 2.25, 2);
    cart.addItem('Milk', 1.2, 3);
    assert.equal(cart.getTotal(), 10.1);
  });

  it('rounds to two decimal places by default so floating-point noise does not leak out', () => {
    cart.addItem('Candy', 0.1, 3);
    assert.equal(cart.getTotal(), 0.3);
    cart.addItem('Shirt', 19.99, 3);
    assert.equal(cart.getTotal(), 60.27);
  });

  it('reflects removals', () => {
    cart.addItem('Apple', 1, 1);
    cart.addItem('Bread', 3, 1);
    cart.removeItem('Bread');
    assert.equal(cart.getTotal(), 1);
  });
});

describe('ShoppingCart#applyDiscount', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
    cart.addItem('Jacket', 80, 1);
    cart.addItem('Socks', 5, 4);
  });

  it('Bug 4 regression: a 10% discount lowers a 100 total to 90, not 110', () => {
    cart.applyDiscount(10);
    assert.equal(cart.getTotal(), 90);
  });

  it('Bug 4 regression: a 25% discount subtracts a quarter of the total', () => {
    cart.applyDiscount(25);
    assert.equal(cart.getTotal(), 75);
  });

  it('leaves the total unchanged with no discount', () => {
    assert.equal(cart.getTotal(), 100);
  });

  it('accepts the boundary values 0 and 100', () => {
    cart.applyDiscount(100);
    assert.equal(cart.getTotal(), 0);
    cart.applyDiscount(0);
    assert.equal(cart.getTotal(), 100);
  });

  it('supports fractional percentages', () => {
    cart.applyDiscount(12.5);
    assert.equal(cart.getTotal(), 87.5);
  });

  it('replaces the previous discount instead of stacking it', () => {
    cart.applyDiscount(10);
    cart.applyDiscount(20);
    assert.equal(cart.discount, 20);
    assert.equal(cart.getTotal(), 80);
  });

  it('applies to items added after the discount was set', () => {
    cart.applyDiscount(50);
    cart.addItem('Hat', 20, 1);
    assert.equal(cart.getTotal(), 60);
  });

  it('rounds a half-cent discounted total up to the nearest cent', () => {
    const small = new ShoppingCart();
    small.addItem('Lunch', 31.5, 1);
    small.applyDiscount(15);
    assert.equal(small.getTotal(), 26.78);
  });

  describe('Bug 5 regression: rejects out-of-range and non-numeric discounts', () => {
    const invalidDiscounts = [
      { value: 101, error: RangeError },
      { value: 150, error: RangeError },
      { value: 100.01, error: RangeError },
      { value: -5, error: RangeError },
      { value: -0.01, error: RangeError },
      { value: NaN, error: RangeError },
      { value: Infinity, error: RangeError },
      { value: '10', error: TypeError },
      { value: null, error: TypeError },
      { value: undefined, error: TypeError },
    ];

    for (const { value, error } of invalidDiscounts) {
      it(`rejects ${String(value)} with a ${error.name} and keeps the previous discount`, () => {
        cart.applyDiscount(10);
        assert.throws(() => cart.applyDiscount(value), { name: error.name, message: /discount/ });
        assert.equal(cart.discount, 10);
        assert.equal(cart.getTotal(), 90);
      });
    }

    it('explains the allowed range in the error message', () => {
      assert.throws(() => cart.applyDiscount(150), {
        message: /discount percent must be at most 100, received 150/,
      });
    });
  });
});

describe('ShoppingCart#getItemCount', () => {
  it('counts distinct line items, not total quantity', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 10);
    cart.addItem('Bread', 2, 1);
    assert.equal(cart.getItemCount(), 2);
  });

  it('does not change when an existing item is merged', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 1);
    cart.addItem('Apple', 0.5, 1);
    assert.equal(cart.getItemCount(), 1);
  });

  it('decreases after a successful removal and not after a missed one', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 1);
    cart.addItem('Bread', 2, 1);
    cart.removeItem('Cheese');
    assert.equal(cart.getItemCount(), 2);
    cart.removeItem('Apple');
    assert.equal(cart.getItemCount(), 1);
  });
});

describe('ShoppingCart end-to-end workflow', () => {
  it('handles add, merge, remove, discount and total together', () => {
    const cart = new ShoppingCart();
    cart.addItem('Coffee', 4.5, 2);
    cart.addItem('Bagel', 2.25, 1);
    cart.addItem('Coffee', 4.5, 1);
    cart.addItem('Juice', 3.75, 2);
    assert.equal(cart.getItemCount(), 3);
    assert.equal(cart.getTotal(), 23.25);

    assert.equal(cart.removeItem('Juice'), true);
    assert.equal(cart.getTotal(), 15.75);

    cart.applyDiscount(20);
    assert.equal(cart.getTotal(), 12.6);

    assert.throws(() => cart.applyDiscount(120), RangeError);
    assert.throws(() => cart.addItem('Refund', -15.75, 1), RangeError);
    assert.equal(cart.removeItem('Juice'), false);
    assert.equal(cart.getTotal(), 12.6);
  });
});

