    const small = new ShoppingCart();
    small.addItem('Lunch', 31.5, 1);
    small.applyDiscount(15);
    assert.equal(small.getTotal(), 26.78);
  });

  describe('Bug 5 regression: rejects out-of-range and non-numeric discounts', () => {
    const invalidDiscounts = [
      { value: 101, error: RangeError },
      { value: 150, error: RangeError },
      { value: 100.01, error: RangeError },
      { value: -5, error: RangeError },
      { value: -0.01, error: RangeError },
      { value: NaN, error: RangeError },
      { value: Infinity, error: RangeError },
      { value: '10', error: TypeError },
      { value: null, error: TypeError },
      { value: undefined, error: TypeError },
    ];

    for (const { value, error } of invalidDiscounts) {
      const label = typeof value === 'string' ? `the string ${JSON.stringify(value)}` : String(value);
      it(`rejects ${label} with a ${error.name} and keeps the previous discount`, () => {
        cart.applyDiscount(10);
        assert.throws(() => cart.applyDiscount(value), { name: error.name, message: /discount/ });
        assert.equal(cart.discount, 10);
        assert.equal(cart.getTotal(), 90);
      });
    }

    it('explains the allowed range in the error message', () => {
      assert.throws(() => cart.applyDiscount(150), {
        message: /discount percent must be at most 100, received 150/,
      });
    });
  });
});

describe('ShoppingCart#getItemCount', () => {
  it('counts distinct line items, not total quantity', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 10);
    cart.addItem('Bread', 2, 1);
    assert.equal(cart.getItemCount(), 2);
  });

  it('does not change when an existing item is merged', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 1);
    cart.addItem('Apple', 0.5, 1);
    assert.equal(cart.getItemCount(), 1);
  });

  it('decreases after a successful removal and not after a missed one', () => {
    const cart = new ShoppingCart();
    cart.addItem('Apple', 0.5, 1);
    cart.addItem('Bread', 2, 1);
    cart.removeItem('Cheese');
    assert.equal(cart.getItemCount(), 2);
    cart.removeItem('Apple');
    assert.equal(cart.getItemCount(), 1);
  });
});

describe('ShoppingCart end-to-end workflow', () => {
  it('handles add, merge, remove, discount and total together', () => {
    const cart = new ShoppingCart();
    cart.addItem('Coffee', 4.5, 2);
    cart.addItem('Bagel', 2.25, 1);
    cart.addItem('Coffee', 4.5, 1);
    cart.addItem('Juice', 3.75, 2);
    assert.equal(cart.getItemCount(), 3);
    assert.equal(cart.getTotal(), 23.25);

    assert.equal(cart.removeItem('Juice'), true);
    assert.equal(cart.getTotal(), 15.75);

    cart.applyDiscount(20);
    assert.equal(cart.getTotal(), 12.6);

    assert.throws(() => cart.applyDiscount(120), RangeError);
    assert.throws(() => cart.addItem('Refund', -15.75, 1), RangeError);
    assert.equal(cart.removeItem('Juice'), false);
    assert.equal(cart.getTotal(), 12.6);
  });
});
